#!/usr/bin/env python3\nimport json, os, subprocess, tempfile\nfrom pathlib import Path\n\ndef main():\n    root=Path(tempfile.mkdtemp(prefix="aoostar-selftest-"))\n    (root/"sensors").mkdir(); (root/"backups").mkdir(); (root/"images").mkdir()\n    panels=[]\n    for i in range(5):\n        elems=[{"type":"lcars_header","text":f"TEST {i+1}","x":18,"y":14,"w":924,"h":42,"size":31,"textColor":"amber","accent":"orange"}]\n        if i==4:\n            elems += [{"type":"bar","label":"cpu_usage_percent","x":50,"y":100,"w":173,"h":17,"max":100,"accent":"violet"},\n                      {"type":"sensor","label":"cpu_usage_percent","title":"CPU","x":50,"y":140,"w":173,"h":70,"size":29,"titleSize":13,"align":"right","titleAlign":"left","unit":"%"}]\n        panels.append({"name":f"TEST-{i+1}","duration":6,"background":"","image":{"mode":"cover","x":0,"y":0,"zoom":1},"elements":elems})\n    layout={"schemaVersion":5,"appVersion":"0.8.7","theme":"lcars-orange","switchTime":6,"panels":panels}\n    (root/"layout-v07.json").write_text(json.dumps(layout))\n    (root/"sensors/values.txt").write_text("cpu_usage_percent: 42.5\\n")\n    env=dict(os.environ); env["AOOSTAR_CFG"]=str(root)\n    r=subprocess.run(["python3","/app/lcd_generator.py"],env=env,capture_output=True,text=True)\n    assert r.returncode==0,(r.stdout,r.stderr)\n    cfg=json.loads((root/"monitor.generated.json").read_text())\n    assert len(cfg["diy"])==5, len(cfg["diy"])\n    assert len(cfg["mianban"])==5, cfg["mianban"]\n    assert (root/"generated/panel_5.png").exists()\n    sensor=cfg["diy"][4]["sensor"][0]\n    assert sensor["fontSize"]==29 and sensor["width"]==173 and sensor["textAlign"]=="right",sensor\n    print("AOOSTAR roundtrip selftest OK: 5 panels")\nif __name__=="__main__": main()\n